fullText:
*{
    line-height: 2;
    margin: 0;
    padding: 0;
}
header{
    background-image: url(filesProjet4/fond.png);
    background-repeat: no-repeat;
    background-size: cover;
    height: 80px;

}
h1{
    color: #FDF0D1;
    text-align: center;
}
#date{
    text-align: right;
    color: #FDF0D1;
    font-weight: bold;

}
ul{
    list-style: none;
    padding-top:  1.5%;
}
nav{
    text-align: center;
}
li{
    display: inline-block;
    background-color: #616d82;
    border: 1px solid #fdf0d1;
    width: 160px;
    text-align: center;
    border-radius: 10px;
    padding: 2px;
}
a{
    text-decoration: none;
    color: #fdf0d1;
    font-weight: bold;
}
main{
    height: 600px;
    background-color:#FDF0D1 ;

}
section{
    width: 60%;
    height: 400px;
    margin: auto;
    margin-top: 6%;
    box-shadow: 1px 2px 3px 8px rgba(49,12,40,0.5);
 
}
iframe{
    width: 100%;
    height: 100%;
}
footer{
    background-color: #616d81;
    height: 60px;
}
p{
    color: #FDF0D1;
    text-align: right;
}
input[type="text"],input[type="number"]{
    border: 1px solid black;
    border-radius: 10px;
    width: 300px;
    height: 40px;
    margin: 2%;
    text-align: center;
}
input[type="reset"],input[type="submit"]{
    border: 1px solid;
    width: 90px;
}
form{
    text-align: center;
}
legend{
    text-decoration: underline;

}

